#include <iostream>
#include <vector>
#include <string>
#include <algorithm>

int main() {
    int countLines;
    std::cin >> countLines;
    std::cin.ignore(); // ignore the newline after the integer input
    std::string lineInput;
    std::getline(std::cin, lineInput);

    // Split the lineInput by parentheses using a simple approach
    std::vector<std::string> splitParts;
    size_t start = 0, end = 0;
    bool inside = false;
    std::string currentPart;
    for (char ch : lineInput) {
        if (ch == '(') {
            if (!currentPart.empty()) {
                splitParts.push_back(currentPart);
                currentPart.clear();
            }
            inside = true;
        } else if (ch == ')') {
            if (!currentPart.empty()) {
                splitParts.push_back(currentPart);
                currentPart.clear();
            }
            inside = false;
        } else {
            currentPart += ch;
        }
    }
    if (!currentPart.empty()) {
        splitParts.push_back(currentPart);
    }

    int maxWordSize = 0;
    for (const auto& part : splitParts) {
        size_t pos = 0, prev = 0;
        while ((pos = part.find('_', prev)) != std::string::npos) {
            std::string token = part.substr(prev, pos - prev);
            maxWordSize = std::max(static_cast<int>(token.length()), maxWordSize);
            prev = pos + 1;
        }
        // last token after the last underscore
        std::string token = part.substr(prev);
        maxWordSize = std::max(static_cast<int>(token.length()), maxWordSize);
    }

    // Extract inside brackets
    std::vector<std::string> insideBrackets;
    size_t startIndex = -1;
    for (size_t i = 0; i < lineInput.length(); ++i) {
        if (lineInput[i] == '(') {
            startIndex = i;
        } else if (lineInput[i] == ')' && startIndex != -1) {
            insideBrackets.push_back(lineInput.substr(startIndex + 1, i - startIndex - 1));
            startIndex = -1;
        }
    }

    int totalWords = 0;
    for (const auto& segment : insideBrackets) {
        size_t prev = 0, pos;
        while ((pos = segment.find('_', prev)) != std::string::npos) {
            if (pos > prev) {
                totalWords++;
            }
            prev = pos + 1;
        }
        if (prev < segment.length()) {
            totalWords++;
        }
    }

    std::cout << maxWordSize << " " << totalWords << std::endl;

    return 0;
}
